// Merge translations into the base French seed data at module load.
for (const entry of ICD10_SEED) {
  const t = ICD10_TRANSLATIONS[entry.code];
  if (!t) continue;
  entry.titleEn = t.titleEn;
  entry.titleDe = t.titleDe;
  entry.titleNl = t.titleNl;
  if (t.descriptionEn !== undefined) entry.descriptionEn = t.descriptionEn;
  if (t.descriptionDe !== undefined) entry.descriptionDe = t.descriptionDe;
  if (t.descriptionNl !== undefined) entry.descriptionNl = t.descriptionNl;
  if (t.risksEn !== undefined) entry.risksEn = t.risksEn;
  if (t.risksDe !== undefined) entry.risksDe = t.risksDe;
  if (t.risksNl !== undefined) entry.risksNl = t.risksNl;
}

async function seedIcd10Codes() {
  for (const entry of ICD10_SEED) {
    await db.insert(icd10CodesTable).values({
      code: entry.code,
      title: entry.title,
      description: entry.description ?? null,
      risks: entry.risks ?? null,
      isFavorite: entry.isFavorite ?? false,
      titleEn: entry.titleEn ?? null,
      titleDe: entry.titleDe ?? null,
      titleNl: entry.titleNl ?? null,
      descriptionEn: entry.descriptionEn ?? null,
      descriptionDe: entry.descriptionDe ?? null,
      descriptionNl: entry.descriptionNl ?? null,
      risksEn: entry.risksEn ?? null,
      risksDe: entry.risksDe ?? null,
      risksNl: entry.risksNl ?? null,
    }).onConflictDoNothing();
  }

  // Backfill translation columns for EXISTING rows: only fill columns that are
  // currently NULL, and never touch the French base fields.
  for (const entry of ICD10_SEED) {
    const translationCols = [
      { column: icd10CodesTable.titleEn, key: "titleEn", value: entry.titleEn },
      { column: icd10CodesTable.titleDe, key: "titleDe", value: entry.titleDe },
      { column: icd10CodesTable.titleNl, key: "titleNl", value: entry.titleNl },
      { column: icd10CodesTable.descriptionEn, key: "descriptionEn", value: entry.descriptionEn },
      { column: icd10CodesTable.descriptionDe, key: "descriptionDe", value: entry.descriptionDe },
      { column: icd10CodesTable.descriptionNl, key: "descriptionNl", value: entry.descriptionNl },
      { column: icd10CodesTable.risksEn, key: "risksEn", value: entry.risksEn },
      { column: icd10CodesTable.risksDe, key: "risksDe", value: entry.risksDe },
      { column: icd10CodesTable.risksNl, key: "risksNl", value: entry.risksNl },
    ] as const;

    for (const { column, key, value } of translationCols) {
      if (value === undefined) continue;
      await db
        .update(icd10CodesTable)
        .set({ [key]: value })
        .where(and(eq(icd10CodesTable.code, entry.code), isNull(column)));
    }
  }
}

export async function seedDatabase() {
  await seedIcd10Codes();

  const defaults: Record<string, string[]> = {
    casemanagers: [],
    psychiatrists: [],
    medecinsfamille: [],
    articles: ["Article 71", "Article 72", "Article 73", "CAPL"],
    curatelles: ["Curatelle totale", "Curatelle partielle", "Tutelle", "Sauvegarde de justice"],
  };

  for (const [key, value] of Object.entries(defaults)) {
    const existing = await db.select().from(settingsTable)
      .where(eq(settingsTable.key, key))
      .limit(1);

    if (!existing[0]) {
      await db.insert(settingsTable).values({ key, value: JSON.stringify(value) });
    }
  }
}
